                <ComposedChart data={bandBars} margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 12 }}
                    domain={[180, 360]}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 12 }}
                    domain={[0, 70]}
                    tickFormatter={(v) => `${v}%`}
                  />
                  <Tooltip />
                  <Legend />
                  <Bar
                    yAxisId="left"
                    dataKey="p25"
                    name="P25 ratio"
                    fill={SLATE}
                    opacity={0.35}
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    yAxisId="left"
                    dataKey="p75"
                    name="P75 ratio"
                    fill={TEAL}
                    opacity={0.55}
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="top1"
                    name="Top-1 share"
                    stroke={NAVY}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "metros" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="HHI ?? price (or system share)"
            subtitle="Bubble size ??? employer lives in claims footprint"
          >
            <div className="mb-3">
              <ToggleGroup
                label="Y metric"
                value={scatterMetric}
                onChange={setScatterMetric}
                options={[
                  { id: "ratio", label: "Price ratio" },
                  { id: "top1", label: "Top-1 share" },
                  { id: "top2", label: "Top-2 share" },
                ]}
              />
            </div>
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%" minWidth={0}>
                <ScatterChart margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="HHI"
                    tick={{ fontSize: 11 }}
                    domain={[800, 6000]}
                    label={{ value: "Admissions HHI", position: "insideBottom", offset: -2, fontSize: 11 }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Y"
                    tick={{ fontSize: 11 }}
                    label={{ value: yLabel, angle: -90, position: "insideLeft", fontSize: 11 }}
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 320]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v: number, name: string) => [
                      name === "x" ? fmtInt(v) : `${Math.round(v)}`,
                      name === "x" ? "HHI" : yLabel,
                    ]}
                    labelFormatter={() => ""}
                    content={({ active, payload }) => {
                      if (!active || !payload?.length) return null;
                      const d = payload[0]?.payload as (typeof scatter)[0];
                      if (!d) return null;
                      return (
                        <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-md">
                          <p className="font-semibold text-slate-900">{d.metro}</p>
                          <p className="text-slate-600">HHI {fmtInt(d.hhi)}</p>
                          <p className="text-slate-600">Ratio {fmtPct(d.ratioPct)}</p>
                          <p className="text-slate-600">
                            Top-1 / Top-2 {fmtPct(d.top1SharePct)} / {fmtPct(d.top2SharePct)}
                          </p>
                        </div>
                      );
                    }}
                  />
                  <Scatter data={scatter} name="Metros">
                    {scatter.map((m) => (
                      <Cell key={m.id} fill={m.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="High-clout tip systems"
            subtitle="Admission share vs commercial/Medicare in tip metros"
          >
