                  <Bar
                    dataKey="admissionSharePct"
                    name="Admission share"
                    fill={INDIGO}
                    radius={[0, 4, 4, 0]}
                  />
                  <Bar
                    dataKey="ratioPct"
                    name="Price ratio"
                    fill={AMBER}
                    radius={[0, 4, 4, 0]}
