    return metrosByRegion(region).map((m) => ({
      ...m,
      x: m.hhi,
      y:
        scatterMetric === "ratio"
          ? m.ratioPct
          : scatterMetric === "top1"
            ? m.top1SharePct
            : m.top2SharePct,
      z: Math.max(80, m.employerLivesK / 8),
