          <span>??</span>
          <span>
            IP {fmtPct(HEADLINE.inpatientRatioPct)} / OP {fmtPct(HEADLINE.outpatientRatioPct)}
          </span>
        </div>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
