"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  HEADLINE,
  HHI_BANDS,
  METRO_PANEL,
  RESIDUALS,
  SERVICE_LINES,
  SOURCE_NOTE,
  TOP_SYSTEMS,
  VINTAGE_PATH,
  fmtInt,
  fmtPct,
  metrosByRegion,
  type RegionId,
} from "@/data/hospital-system-clout-vs-commercial-prices-2026-data";

// viz-types: HHI-band bars, metro HHI??ratio scatter, vintage area+line,
// service-line bars, top-system ladder, residual bars | layout: default

type ViewId = "bands" | "metros" | "services" | "path";
type RegionFilter = "all" | RegionId;
type ScatterMetric = "ratio" | "top1" | "top2";

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const SLATE = "#64748b";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";

const REGION_COLORS: Record<string, string> = {
  Northeast: INDIGO,
  Midwest: TEAL,
  South: ROSE,
  West: AMBER,
};

const BAND_COLORS = [SKY, TEAL, AMBER, ROSE];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function HospitalSystemCloutVsCommercialPrices2026Dashboard() {
  const [view, setView] = useState<ViewId>("bands");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [scatterMetric, setScatterMetric] = useState<ScatterMetric>("ratio");

  const bandBars = useMemo(
    () =>
      HHI_BANDS.map((b, i) => ({
        name: b.label,
        range: b.hhiRange,
        mean: b.meanRatioPct,
        p25: b.p25RatioPct,
        p75: b.p75RatioPct,
        top1: b.meanTop1SharePct,
        fill: BAND_COLORS[i],
        cbsas: b.cbsaCount,
      })),
    [],
  );

  const scatter = useMemo(() => {
    return metrosByRegion(region).map((m) => ({
      ...m,
      x: m.hhi,
      y:
        scatterMetric === "ratio"
          ? m.ratioPct
          : scatterMetric === "top1"
            ? m.top1SharePct
            : m.top2SharePct,
      z: Math.max(80, m.employerLivesK / 8),
      fill: REGION_COLORS[m.region],
    }));
  }, [region, scatterMetric]);

  const serviceBars = useMemo(
    () =>
      SERVICE_LINES.map((s) => ({
        name: s.label,
        ratio: s.ratioPct,
        spend: s.spendSharePct,
        slope: s.hhiSlopePpPer1000,
      })),
    [],
  );

  const vintage = useMemo(
    () =>
      VINTAGE_PATH.map((v) => ({
        year: String(v.year),
        ratio: v.nationalRatioPct,
        hhi: v.meanHhi / 100,
        highShare: v.highSharePct,
      })),
    [],
  );

  const systems = useMemo(() => {
    let rows = TOP_SYSTEMS;
    if (region !== "all") rows = rows.filter((r) => r.region === region);
    return [...rows].sort((a, b) => b.admissionSharePct - a.admissionSharePct);
  }, [region]);

  const residuals = useMemo(
    () => [...RESIDUALS].sort((a, b) => b.residualPp - a.residualPp),
