                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 12 }}
                    domain={[28, 42]}
                  />
                  <Tooltip />
                  <Legend />
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="ratio"
                    name="Nat'l ratio %"
                    fill={TEAL}
                    fillOpacity={0.25}
                    stroke={TEAL}
                    strokeWidth={2}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="hhi"
                    name="Mean HHI / 100"
                    stroke={NAVY}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
