                          <p className="text-slate-600">Ratio {fmtPct(d.ratioPct)}</p>
                          <p className="text-slate-600">
                            Top-1 / Top-2 {fmtPct(d.top1SharePct)} / {fmtPct(d.top2SharePct)}
                          </p>
                        </div>
                      );
                    }}
                  />
                  <Scatter data={scatter} name="Metros">
                    {scatter.map((m) => (
                      <Cell key={m.id} fill={m.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
