                  />
                  <Legend />
                  <Bar
                    dataKey="admissionSharePct"
                    name="Admission share"
                    fill={INDIGO}
                    radius={[0, 4, 4, 0]}
                  />
                  <Bar
                    dataKey="ratioPct"
