import fs from "fs";
const t = fs.readFileSync("src/data/posts.ts", "utf8");
const start = t.indexOf('slug: "hospital-system-clout-vs-commercial-prices-2026"');
const c0 = t.indexOf("content: `", start) + "content: `".length;
// find closing backtick before next post's id field at same indent
let i = c0;
let depth = 0;
while (i < t.length) {
  if (t[i] === "`" && t.slice(i-1,i+3) !== "\\`") {
    // check if this closes content - look for ,\n after
    if (t.slice(i, i+5).match(/^`,\r?\n/)) { break; }
  }
  i++;
}
const content = t.slice(c0, i);
const words = content.trim().split(/\s+/).length;
const h2s = [...content.matchAll(/^## .+$/gm)].map(m => m[0]);
console.log({ words, h2: h2s.length, h2s, chars: content.length });
